const invItems = $('Fetch Product Inventory Sheet').all();
const ratesItems = $('Fetch Shipping & Packing Rates Sheet').all();
const payItems = $('Fetch Payment Methods Sheet').all();

// Check if simulation failure header or parameter was passed
let simulateFailure = false;
try {
  const trigItems = $('Webhook Trigger').all();
  if (trigItems.length > 0 && trigItems[0]?.json?.headers && (trigItems[0].json.headers['x-simulate-failure'] === 'true' || trigItems[0].json.body?.simulate_failure === true)) {
    simulateFailure = true;
  }
} catch (e) {}

// Check if any node returned an API error
const firstInv = invItems[0]?.json || {};
const firstRates = ratesItems[0]?.json || {};
const firstPay = payItems[0]?.json || {};

if (firstInv.error || firstRates.error || firstPay.error || simulateFailure) {
  const errMsg = simulateFailure ? 'Simulated Google Sheets API network timeout / invalid sheet format' : (firstInv.error?.message || firstRates.error?.message || firstPay.error?.message || 'Google Sheets API error');
  return {
    status: 'FAILED',
    error: errMsg,
    productsCount: 0
  };
}

// 1. Parse Product Inventory
let parsedProducts = [];
let deliveryDays = 'Monday–Wednesday only';
let idCounter = 1;

for (const item of invItems) {
  const row = item.json;
  const rawMember = String(row['SASH\'S PRODUCT INVENTORY ♡'] || row['Member'] || row['member'] || '').trim();
  const rawProd = String(row['col_2'] || row['Product Name'] || row['product_name'] || '').trim();
  const rawPrice = row['col_3'] !== undefined ? row['col_3'] : (row['Price (₱)'] || row['Price'] || '0');
  const rawStock = row['col_4'] !== undefined ? row['col_4'] : (row['Stock (pcs)'] || row['Stock'] || '0');
  const rawNotes = String(row['col_5'] || row['Notes'] || row['notes'] || '').trim();

  if (rawMember.includes('Delivery days:')) {
    const parts = rawMember.split('Delivery days:');
    if (parts[1]) deliveryDays = parts[1].trim();
  }

  if (rawMember && rawProd && rawMember !== 'Member' && !rawMember.includes('PRODUCT INVENTORY')) {
    const price = parseInt(String(rawPrice).replace(/[^0-9]/g, ''), 10) || 0;
    const stock = parseInt(String(rawStock).replace(/[^0-9]/g, ''), 10) || 0;
    const mClean = rawMember.toUpperCase();
    parsedProducts.push({
      id: idCounter++,
      member: mClean,
      product_name: rawProd,
      price_php: price,
      stock,
      notes: rawNotes,
      keywords: `${mClean} ${rawProd} ${rawNotes}`.toLowerCase()
    });
  }
}

// 2. Parse Shipping & Packing Rates
let courier = 'J&T Express (all rates include a ₱21 voucher)';
let shippingRates = [];
let packingFees = [];

for (const item of ratesItems) {
  const row = item.json;
  const col1 = String(row['SHIPPING FEE AND PACKING FEE RATES'] || row['LOCATION'] || '').trim().toUpperCase();
  const col2 = row['col_2'];
  const col3 = row['col_3'];
  const col4 = row['col_4'];

  if (col1.includes('MODE OF SHIPMENT:')) {
    courier = String(row['SHIPPING FEE AND PACKING FEE RATES'] || '').trim();
  } else if (['LUZON', 'VISAYAS', 'MINDANAO'].includes(col1)) {
    shippingRates.push({
      region: col1.charAt(0) + col1.slice(1).toLowerCase(),
      small: parseInt(col2, 10) || 0,
      medium: parseInt(col3, 10) || 0,
      large: parseInt(col4, 10) || 0
    });
  } else if (['SMALL', 'MEDIUM', 'LARGE'].includes(col1)) {
    const price = parseInt(String(col2 || '0').replace(/[^0-9]/g, ''), 10) || 0;
    packingFees.push({
      size: col1.charAt(0) + col1.slice(1).toLowerCase(),
      price_php: price,
      capacity: String(col3 || '').trim(),
      inclusions: String(col4 || '').trim()
    });
  }
}

// 3. Parse Payment Methods
let paymentDeadline = '1 week from reservation';
let downpayment = '30% non-refundable downpayment (nrdp)';
let paymentMethods = [];

for (const item of payItems) {
  const row = item.json;
  const col1 = String(row['MODE OF PAYMENT'] || '').trim();
  const col2 = String(row['col_2'] || '').trim();
  const col3 = String(row['col_3'] || '').trim();

  if (col1.toLowerCase().includes('deadline')) {
    paymentDeadline = col1;
  } else if (col1 && col2) {
    paymentMethods.push({
      method_name: col1,
      account_number: col2,
      account_name: col3
    });
  }
}

// Validation gate: Reject malformed or empty imports without corrupting existing database
const isValid = parsedProducts.length >= 50 && shippingRates.length === 3 && packingFees.length === 3 && paymentMethods.length >= 1;
if (!isValid) {
  return {
    status: 'FAILED',
    error: `Validation failed: parsed ${parsedProducts.length} products, ${shippingRates.length} shipping regions, ${packingFees.length} packing tiers, ${paymentMethods.length} payment methods.`,
    productsCount: parsedProducts.length
  };
}

// Build transactional SQL
let sql = 'BEGIN;\n';
sql += 'TRUNCATE TABLE inventory_products, shipping_rates, packing_fees, payment_methods RESTART IDENTITY;\n';

// Insert Shipping Rates
for (const sr of shippingRates) {
  sql += `INSERT INTO shipping_rates (region, small, medium, large) VALUES ('${sr.region}', ${sr.small}, ${sr.medium}, ${sr.large});\n`;
}

// Insert Packing Fees
for (const pf of packingFees) {
  const cap = pf.capacity.replace(/'/g, "''");
  const inc = pf.inclusions.replace(/'/g, "''");
  sql += `INSERT INTO packing_fees (size, price_php, capacity, inclusions) VALUES ('${pf.size}', ${pf.price_php}, '${cap}', '${inc}');\n`;
}

// Insert Payment Methods
for (const pm of paymentMethods) {
  const m = pm.method_name.replace(/'/g, "''");
  const num = pm.account_number.replace(/'/g, "''");
  const name = pm.account_name.replace(/'/g, "''");
  sql += `INSERT INTO payment_methods (method_name, account_number, account_name) VALUES ('${m}', '${num}', '${name}');\n`;
}

// Insert Shop Policies
sql += `INSERT INTO shop_policies (policy_key, policy_value) VALUES ('delivery_days', '${deliveryDays.replace(/'/g, "''")}') ON CONFLICT (policy_key) DO UPDATE SET policy_value = EXCLUDED.policy_value;\n`;
sql += `INSERT INTO shop_policies (policy_key, policy_value) VALUES ('courier', '${courier.replace(/'/g, "''")}') ON CONFLICT (policy_key) DO UPDATE SET policy_value = EXCLUDED.policy_value;\n`;
sql += `INSERT INTO shop_policies (policy_key, policy_value) VALUES ('payment_deadline', '${paymentDeadline.replace(/'/g, "''")}') ON CONFLICT (policy_key) DO UPDATE SET policy_value = EXCLUDED.policy_value;\n`;
sql += `INSERT INTO shop_policies (policy_key, policy_value) VALUES ('payment_downpayment', '${downpayment.replace(/'/g, "''")}') ON CONFLICT (policy_key) DO UPDATE SET policy_value = EXCLUDED.policy_value;\n`;

// Insert Products
for (const p of parsedProducts) {
  const m = p.member.replace(/'/g, "''");
  const pn = p.product_name.replace(/'/g, "''");
  const n = p.notes.replace(/'/g, "''");
  const kw = p.keywords.replace(/'/g, "''");
  sql += `INSERT INTO inventory_products (id, member, product_name, price_php, stock, notes, keywords) VALUES (${p.id}, '${m}', '${pn}', ${p.price_php}, ${p.stock}, '${n}', '${kw}');\n`;
}

// Record successful sync history
sql += `INSERT INTO sync_history (sync_type, status, products_synced, error_message, synced_at) VALUES ('GOOGLE_SHEETS', 'SUCCESS', ${parsedProducts.length}, NULL, NOW());\n`;
sql += 'COMMIT;';

return {
  status: 'SUCCESS',
  productsCount: parsedProducts.length,
  shippingCount: shippingRates.length,
  packingCount: packingFees.length,
  paymentCount: paymentMethods.length,
  sqlTransaction: sql
};

